Good point. Let me examine the existing API protocol and service contracts in the spec repo to understand how the lifecycle should be modeled end-to-end.非常好的提醒。你说得对 — spec 中定义的协议不能仅停留在 Zod schema 层面，必须同时考虑 **API 端点** 和 **Runtime 服务端合约**。让我基于现有架构模式做完整的补充设计。

---

# 补充评估：Interface Lifecycle 的 API + Runtime 服务端协议

## 当前架构模式回顾

ObjectStack 的协议设计遵循一个清晰的三层模式：

```
┌─────────────────────────────────────────────────────────────────────┐
│  1. Zod Schema Layer    (packages/spec/src/)                       │
│     定义数据结构 → DeployBundleSchema, ViewSchema, AppSchema       │
├─────────────────────────────────────────────────────────────────────┤
│  2. Service Contract    (packages/spec/src/contracts/)             │
│     定义接口合约 → IMetadataService, IDeployPipelineService       │
├─────────────────────────────────────────────────────────────────────┤
│  3. API Protocol        (packages/spec/src/api/)                   │
│     定义 REST 端点 → protocol.zod.ts, plugin-rest-api.zod.ts      │
│     定义 Protocol接口 → ObjectStackProtocol                       │
├─────────────────────────────────────────────────────────────────────┤
│  4. Runtime Implementation (packages/runtime/, packages/metadata/) │
│     实现服务 → MetadataManager, HttpDispatcher                     │
└─────────────────────────────────────────────────────────────────────┘
```

参考已有的模式（`IDeployPipelineService` + `deploy-bundle.zod.ts` + `ObjectStackProtocol`），Interface Lifecycle 需要在 **每一层** 都有对应产出物。

---

## 完整协议设计

### Layer 1: Zod Schema — `interface-lifecycle.zod.ts`

```typescript name=packages/spec/src/ui/interface-lifecycle.zod.ts
// Copyright (c) 2025 ObjectStack. Licensed under the Apache-2.0 license.

import { z } from 'zod';

/**
 * Interface Lifecycle Protocol
 *
 * Defines the draft → published → archived lifecycle for Interfaces,
 * mirroring Airtable's "Design / Unpublished Changes / Publish" pattern.
 *
 * Architecture alignment:
 * - Airtable: Interface has "unpublished changes" state, one-click Publish
 * - Salesforce: FlexiPage has "Draft" vs "Active" activation status
 * - Retool: Apps have "Edit mode" → "Deploy" flow with version history
 *
 * Data flow:
 *   Designer edits → Auto-save to Draft → [Publish] → Snapshot to Version → Serve Published
 *
 * The runtime serves ONLY the published version to end-users.
 * Designers see the draft version in the builder.
 */

// ==========================================================================
// 1. Lifecycle Status
// ==========================================================================

/**
 * Interface lifecycle status.
 *
 * - `draft`: Never published, work in progress
 * - `published`: Live version matches last edit (clean state)
 * - `modified`: Has unpublished changes since last publish (dirty state)
 * - `archived`: Soft-deleted, not accessible to end-users
 */
export const InterfaceLifecycleStatusEnum = z.enum([
  'draft',
  'published',
  'modified',
  'archived',
]);
export type InterfaceLifecycleStatus = z.infer<typeof InterfaceLifecycleStatusEnum>;

// ==========================================================================
// 2. Version Snapshot
// ==========================================================================

/**
 * Immutable snapshot of an interface at publish time.
 * Once created, a version is never modified.
 */
export const InterfaceVersionSchema = z.object({
  /** Auto-incrementing version number */
  version: z.number().int().min(1).describe('Version number'),

  /** Full serialized interface definition at publish time */
  snapshot: z.record(z.string(), z.unknown())
    .describe('Serialized InterfaceSchema at publish time'),

  /** User who published this version */
  publishedBy: z.string().optional().describe('User ID of publisher'),

  /** Publish timestamp (ISO 8601) */
  publishedAt: z.string().datetime().describe('When this version was published'),

  /** Optional release note */
  changeNote: z.string().optional().describe('Release note for this version'),

  /** SHA256 of snapshot for integrity checking */
  checksum: z.string().optional().describe('SHA256 checksum of snapshot'),
});
export type InterfaceVersion = z.infer<typeof InterfaceVersionSchema>;

// ==========================================================================
// 3. Draft State (Mutable Working Copy)
// ==========================================================================

/**
 * Interface Draft State — tracks the mutable working copy
 * and its relationship to the published version.
 *
 * This is the primary state object persisted by the runtime.
 */
export const InterfaceDraftStateSchema = z.object({
  /** Interface name (immutable identifier) */
  interfaceName: z.string().regex(/^[a-z_][a-z0-9_]*$/)
    .describe('Interface identifier (snake_case)'),

  /** Current lifecycle status */
  status: InterfaceLifecycleStatusEnum.describe('Current lifecycle status'),

  /** Mutable working copy (auto-saved) */
  draft: z.record(z.string(), z.unknown())
    .describe('Current working InterfaceSchema'),

  /** Currently published version number (null if never published) */
  publishedVersion: z.number().int().optional()
    .describe('Last published version number'),

  /** Snapshot of the published version (for diff/revert) */
  publishedSnapshot: z.record(z.string(), z.unknown()).optional()
    .describe('Snapshot of the currently live version'),

  /** Last publish timestamp */
  lastPublishedAt: z.string().datetime().optional()
    .describe('When last published'),

  /** Last auto-save timestamp */
  lastSavedAt: z.string().datetime().optional()
    .describe('When draft was last auto-saved'),

  /** Whether the draft differs from published */
  hasUnpublishedChanges: z.boolean().default(false)
    .describe('Whether draft differs from published version'),
});
export type InterfaceDraftState = z.infer<typeof InterfaceDraftStateSchema>;

// ==========================================================================
// 4. Publish Request / Response
// ==========================================================================

/**
 * Publish Interface Request
 */
export const PublishInterfaceRequestSchema = z.object({
  /** Interface name */
  interfaceName: z.string().describe('Interface to publish'),

  /** Optional release note */
  changeNote: z.string().optional().describe('Release note'),

  /** Whether to validate before publishing */
  validate: z.boolean().default(true).describe('Validate interface before publish'),
});
export type PublishInterfaceRequest = z.infer<typeof PublishInterfaceRequestSchema>;

/**
 * Publish Interface Response
 */
export const PublishInterfaceResponseSchema = z.object({
  /** Whether publish succeeded */
  success: z.boolean(),

  /** New version number */
  version: z.number().int().optional(),

  /** Publish timestamp */
  publishedAt: z.string().datetime().optional(),

  /** Validation errors (if validate=true and failed) */
  validationErrors: z.array(z.object({
    path: z.string(),
    message: z.string(),
  })).optional(),
});
export type PublishInterfaceResponse = z.infer<typeof PublishInterfaceResponseSchema>;

// ==========================================================================
// 5. Revert / Rollback
// ==========================================================================

/**
 * Revert Draft to Published Request
 */
export const RevertDraftRequestSchema = z.object({
  interfaceName: z.string().describe('Interface to revert'),
  /** Revert to a specific version (defaults to current published) */
  targetVersion: z.number().int().optional()
    .describe('Version to revert to (default: current published)'),
});

export const RevertDraftResponseSchema = z.object({
  success: z.boolean(),
  revertedToVersion: z.number().int().optional(),
});

// ==========================================================================
// 6. Version History
// ==========================================================================

/**
 * List Version History Request
 */
export const ListVersionsRequestSchema = z.object({
  interfaceName: z.string().describe('Interface name'),
  limit: z.number().int().min(1).max(100).default(20)
    .describe('Max versions to return'),
  offset: z.number().int().min(0).default(0),
});

export const ListVersionsResponseSchema = z.object({
  interfaceName: z.string(),
  versions: z.array(InterfaceVersionSchema),
  total: z.number().int(),
});

// ==========================================================================
// 7. Diff
// ==========================================================================

/**
 * Diff between draft and published version.
 */
export const InterfaceDiffSchema = z.object({
  interfaceName: z.string(),
  hasChanges: z.boolean(),
  changes: z.array(z.object({
    path: z.string().describe('JSON path of change (e.g. "pages[0].label")'),
    type: z.enum(['added', 'modified', 'removed']),
    oldValue: z.unknown().optional(),
    newValue: z.unknown().optional(),
  })),
  summary: z.object({
    pagesAdded: z.number().int().default(0),
    pagesRemoved: z.number().int().default(0),
    pagesModified: z.number().int().default(0),
    elementsAdded: z.number().int().default(0),
    elementsRemoved: z.number().int().default(0),
    elementsModified: z.number().int().default(0),
  }),
});
export type InterfaceDiff = z.infer<typeof InterfaceDiffSchema>;
```

### Layer 2: Service Contract — `IInterfaceLifecycleService`

参照 [`IDeployPipelineService`](https://github.com/objectstack-ai/spec/blob/d80ec966c1d75b055593856ee44043d221be53a7/packages/spec/src/contracts/deploy-pipeline-service.ts) 和 [`IAppLifecycleService`](https://github.com/objectstack-ai/spec/blob/d80ec966c1d75b055593856ee44043d221be53a7/packages/spec/src/contracts/app-lifecycle-service.ts) 的模式：

```typescript name=packages/spec/src/contracts/interface-lifecycle-service.ts
// Copyright (c) 2025 ObjectStack. Licensed under the Apache-2.0 license.

/**
 * IInterfaceLifecycleService - Interface Design/Stage/Publish Contract
 *
 * Manages the full lifecycle of Airtable-style Interfaces:
 * 1. Create/load draft
 * 2. Auto-save draft changes
 * 3. Diff draft vs published
 * 4. Validate before publish
 * 5. Publish (snapshot draft → new version)
 * 6. Revert to previous version
 * 7. Archive / restore
 *
 * Aligned with CoreServiceName 'interface-lifecycle' in core-services.zod.ts.
 *
 * ## Relationship to IMetadataService
 * - IMetadataService stores the *published* interface definition (type='interface')
 * - IInterfaceLifecycleService manages the *draft* + *version history*
 * - On publish, this service calls IMetadataService.register('interface', name, snapshot)
 *
 * ## Relationship to IDeployPipelineService
 * - Interface publish does NOT trigger DDL changes (it's UI metadata only)
 * - But if interface references new objects/fields, IDeployPipelineService handles that separately
 */

import type {
  InterfaceDraftState,
  InterfaceVersion,
  InterfaceDiff,
  PublishInterfaceRequest,
  PublishInterfaceResponse,
  InterfaceLifecycleStatus,
} from '../ui/interface-lifecycle.zod.js';

// ==========================================================================
// Service Interface
// ==========================================================================

export interface IInterfaceLifecycleService {

  // ==========================================
  // Draft Management
  // ==========================================

  /**
   * Get the current draft state of an interface.
   * Returns the mutable working copy + lifecycle status.
   *
   * @param tenantId - Tenant context
   * @param interfaceName - Interface identifier
   * @returns Draft state, or null if not found
   */
  getDraftState(tenantId: string, interfaceName: string): Promise<InterfaceDraftState | null>;

  /**
   * Save draft changes (auto-save endpoint).
   * Debounced by the client, but the server accepts any frequency.
   * Updates `lastSavedAt`, sets `hasUnpublishedChanges = true`,
   * transitions status to 'modified' if currently 'published'.
   *
   * @param tenantId - Tenant context
   * @param interfaceName - Interface identifier
   * @param draft - Partial or full draft update
   * @returns Updated draft state
   */
  saveDraft(
    tenantId: string,
    interfaceName: string,
    draft: Record<string, unknown>,
  ): Promise<InterfaceDraftState>;

  /**
   * Create a new interface in draft status.
   *
   * @param tenantId - Tenant context
   * @param interfaceName - Interface identifier (snake_case)
   * @param initialDraft - Initial interface definition
   * @returns Created draft state
   */
  createDraft(
    tenantId: string,
    interfaceName: string,
    initialDraft: Record<string, unknown>,
  ): Promise<InterfaceDraftState>;

  // ==========================================
  // Publish / Revert
  // ==========================================

  /**
   * Publish the current draft as a new version.
   * 1. Validates draft (if request.validate = true)
   * 2. Creates immutable version snapshot
   * 3. Updates metadata registry (IMetadataService.register)
   * 4. Transitions status to 'published'
   * 5. Clears hasUnpublishedChanges
   *
   * @param tenantId - Tenant context
   * @param request - Publish request with optional change note
   * @returns Publish result with version number
   */
  publish(tenantId: string, request: PublishInterfaceRequest): Promise<PublishInterfaceResponse>;

  /**
   * Revert draft to a published version.
   * Replaces draft content with the snapshot of the target version.
   * Does NOT change the published version — only resets the draft.
   *
   * @param tenantId - Tenant context
   * @param interfaceName - Interface identifier
   * @param targetVersion - Version to revert to (default: current published)
   * @returns Success status
   */
  revertDraft(
    tenantId: string,
    interfaceName: string,
    targetVersion?: number,
  ): Promise<{ success: boolean; revertedToVersion?: number }>;

  // ==========================================
  // Diff
  // ==========================================

  /**
   * Compute diff between current draft and published version.
   * Used by the UI to show "unpublished changes" summary.
   *
   * @param tenantId - Tenant context
   * @param interfaceName - Interface identifier
   * @returns Structured diff with change details
   */
  getDiff(tenantId: string, interfaceName: string): Promise<InterfaceDiff>;

  // ==========================================
  // Version History
  // ==========================================

  /**
   * List published version history for an interface.
   *
   * @param tenantId - Tenant context
   * @param interfaceName - Interface identifier
   * @param limit - Max versions to return
   * @param offset - Pagination offset
   * @returns Array of version snapshots (newest first)
   */
  listVersions(
    tenantId: string,
    interfaceName: string,
    limit?: number,
    offset?: number,
  ): Promise<{ versions: InterfaceVersion[]; total: number }>;

  /**
   * Get a specific version snapshot.
   *
   * @param tenantId - Tenant context
   * @param interfaceName - Interface identifier
   * @param version - Version number
   * @returns Version snapshot
   */
  getVersion(
    tenantId: string,
    interfaceName: string,
    version: number,
  ): Promise<InterfaceVersion | null>;

  // ==========================================
  // Lifecycle Operations
  // ==========================================

  /**
   * Archive an interface (soft delete).
   * Removes from end-user access but preserves all versions.
   */
  archive(tenantId: string, interfaceName: string): Promise<void>;

  /**
   * Restore an archived interface.
   * Re-publishes the last published version.
   */
  restore(tenantId: string, interfaceName: string): Promise<void>;

  /**
   * Delete an interface permanently.
   * Removes draft, all versions, and metadata registration.
   * Requires confirmation (irreversible).
   */
  deletePermanently(tenantId: string, interfaceName: string): Promise<void>;
}
```

### Layer 3: API Protocol — REST 端点 + ObjectStackProtocol 扩展

参照 [`protocol.zod.ts`](https://github.com/objectstack-ai/spec/blob/d80ec966c1d75b055593856ee44043d221be53a7/packages/spec/src/api/protocol.zod.ts) 和 [`plugin-rest-api.zod.ts`](https://github.com/objectstack-ai/spec/blob/d80ec966c1d75b055593856ee44043d221be53a7/packages/spec/src/api/plugin-rest-api.zod.ts)：

```typescript name=packages/spec/src/api/interface-lifecycle-api.zod.ts
// Copyright (c) 2025 ObjectStack. Licensed under the Apache-2.0 license.

/**
 * Interface Lifecycle REST API Definition
 *
 * Endpoint registration for the plugin-rest-api system.
 * Maps IInterfaceLifecycleService methods to HTTP endpoints.
 *
 * Follows the same pattern as View Management endpoints in protocol.zod.ts.
 */

// ==========================================================================
// REST Endpoint Registry (for plugin-rest-api.zod.ts)
// ==========================================================================

/**
 * Interface Lifecycle API Plugin Route Group
 *
 * Prefix: /api/v1/interfaces
 * Service: interface-lifecycle
 *
 * Endpoint Map:
 * ┌─────────────────────────────────────────────────────────────────────────┐
 * │  方法   │  HTTP   │  Endpoint                                         │
 * ├─────────┼─────────┼───────────────────────────────────────────────────┤
 * │ Draft   │  GET    │  /api/v1/interfaces/:name/draft                   │
 * │ Save    │  PUT    │  /api/v1/interfaces/:name/draft                   │
 * │ Create  │  POST   │  /api/v1/interfaces                               │
 * │ Publish │  POST   │  /api/v1/interfaces/:name/publish                 │
 * │ Revert  │  POST   │  /api/v1/interfaces/:name/revert                  │
 * │ Diff    │  GET    │  /api/v1/interfaces/:name/diff                    │
 * │ List V  │  GET    │  /api/v1/interfaces/:name/versions                │
 * │ Get V   │  GET    │  /api/v1/interfaces/:name/versions/:version       │
 * │ Archive │  POST   │  /api/v1/interfaces/:name/archive                 │
 * │ Restore │  POST   │  /api/v1/interfaces/:name/restore                 │
 * │ Delete  │  DELETE │  /api/v1/interfaces/:name                         │
 * │ List    │  GET    │  /api/v1/interfaces                               │
 * │ Published│ GET    │  /api/v1/interfaces/:name/published               │
 * └─────────┴─────────┴───────────────────────────────────────────────────┘
 *
 * 注意: 端用户 runtime 只需要 GET /published 端点。
 * 设计器需要所有端点。
 */
export const INTERFACE_LIFECYCLE_ROUTES = {
  prefix: '/api/v1/interfaces',
  service: 'interface-lifecycle',
  category: 'ui',
  authRequired: true,
  endpoints: [
    // --- Draft Management ---
    {
      method: 'GET' as const,
      path: '/:name/draft',
      handler: 'getDraftState',
      summary: 'Get current draft state of an interface',
      tags: ['Interface Lifecycle'],
      responseSchema: 'InterfaceDraftStateSchema',
    },
    {
      method: 'PUT' as const,
      path: '/:name/draft',
      handler: 'saveDraft',
      summary: 'Auto-save draft changes',
      description: 'Called by the designer on debounced edit. Server always accepts.',
      tags: ['Interface Lifecycle'],
      requestSchema: 'InterfaceDraftStateSchema',
      responseSchema: 'InterfaceDraftStateSchema',
    },
    {
      method: 'POST' as const,
      path: '',
      handler: 'createDraft',
      summary: 'Create new interface in draft status',
      tags: ['Interface Lifecycle'],
      responseSchema: 'InterfaceDraftStateSchema',
    },

    // --- Publish / Revert ---
    {
      method: 'POST' as const,
      path: '/:name/publish',
      handler: 'publish',
      summary: 'Publish current draft as new version',
      description: 'Validates, snapshots, registers in metadata, transitions to published.',
      tags: ['Interface Lifecycle'],
      requestSchema: 'PublishInterfaceRequestSchema',
      responseSchema: 'PublishInterfaceResponseSchema',
    },
    {
      method: 'POST' as const,
      path: '/:name/revert',
      handler: 'revertDraft',
      summary: 'Revert draft to a published version',
      tags: ['Interface Lifecycle'],
      requestSchema: 'RevertDraftRequestSchema',
      responseSchema: 'RevertDraftResponseSchema',
    },

    // --- Diff ---
    {
      method: 'GET' as const,
      path: '/:name/diff',
      handler: 'getDiff',
      summary: 'Compute diff between draft and published',
      tags: ['Interface Lifecycle'],
      responseSchema: 'InterfaceDiffSchema',
    },

    // --- Version History ---
    {
      method: 'GET' as const,
      path: '/:name/versions',
      handler: 'listVersions',
      summary: 'List published version history',
      tags: ['Interface Lifecycle'],
      responseSchema: 'ListVersionsResponseSchema',
    },
    {
      method: 'GET' as const,
      path: '/:name/versions/:version',
      handler: 'getVersion',
      summary: 'Get a specific version snapshot',
      tags: ['Interface Lifecycle'],
      responseSchema: 'InterfaceVersionSchema',
    },

    // --- Lifecycle ---
    {
      method: 'POST' as const,
      path: '/:name/archive',
      handler: 'archive',
      summary: 'Archive interface (soft delete)',
      tags: ['Interface Lifecycle'],
    },
    {
      method: 'POST' as const,
      path: '/:name/restore',
      handler: 'restore',
      summary: 'Restore archived interface',
      tags: ['Interface Lifecycle'],
    },
    {
      method: 'DELETE' as const,
      path: '/:name',
      handler: 'deletePermanently',
      summary: 'Permanently delete interface and all versions',
      tags: ['Interface Lifecycle'],
    },

    // --- Runtime (end-user facing) ---
    {
      method: 'GET' as const,
      path: '',
      handler: 'listInterfaces',
      summary: 'List all interfaces (with status)',
      tags: ['Interface Lifecycle'],
      cacheable: true,
      cacheTtl: 60,
    },
    {
      method: 'GET' as const,
      path: '/:name/published',
      handler: 'getPublished',
      summary: 'Get the published version of an interface (runtime)',
      description: 'This is the ONLY endpoint end-users need. Returns the published snapshot.',
      tags: ['Interface Runtime'],
      cacheable: true,
      cacheTtl: 300,
    },
  ],
} as const;
