### Layer 4: Runtime 实现参考架构

```typescript name=packages/runtime/src/services/interface-lifecycle-service.ts
// Pseudo-code: Runtime implementation reference

/**
 * Interface Lifecycle Service Implementation
 *
 * Storage architecture:
 * - Drafts: metadata table (type='interface_draft', scope='platform')
 * - Versions: metadata table (type='interface_version', scope='system')
 * - Published: metadata table (type='interface', scope='platform') ← IMetadataService
 *
 * The implementation uses IMetadataService for persistence:
 * - Draft storage: metadata.register('interface_draft', name, draftState)
 * - Version storage: metadata.register('interface_version', `${name}__v${version}`, snapshot)
 * - Published registration: metadata.register('interface', name, publishedSnapshot)
 */

export class InterfaceLifecycleServiceImpl implements IInterfaceLifecycleService {
  constructor(
    private metadata: IMetadataService,
    private logger: Logger,
  ) {}

  async getDraftState(tenantId: string, interfaceName: string): Promise<InterfaceDraftState | null> {
    return await this.metadata.get('interface_draft', interfaceName) as InterfaceDraftState | null;
  }

  async saveDraft(tenantId: string, interfaceName: string, draft: Record<string, unknown>): Promise<InterfaceDraftState> {
    const current = await this.getDraftState(tenantId, interfaceName);
    if (!current) throw new Error(`Interface ${interfaceName} not found`);

    const updated: InterfaceDraftState = {
      ...current,
      draft,
      lastSavedAt: new Date().toISOString(),
      hasUnpublishedChanges: true,
      status: current.status === 'published' ? 'modified' : current.status,
    };

    await this.metadata.register('interface_draft', interfaceName, updated);
    return updated;
  }

  async publish(tenantId: string, request: PublishInterfaceRequest): Promise<PublishInterfaceResponse> {
    const state = await this.getDraftState(tenantId, request.interfaceName);
    if (!state) return { success: false, validationErrors: [{ path: '', message: 'Not found' }] };

    // 1. Validate (optional)
    if (request.validate) {
      const validation = await this.validateInterface(state.draft);
      if (!validation.valid) {
        return { success: false, validationErrors: validation.errors };
      }
    }

    // 2. Create version snapshot
    const newVersion = (state.publishedVersion ?? 0) + 1;
    const publishedAt = new Date().toISOString();
    const versionEntry: InterfaceVersion = {
      version: newVersion,
      snapshot: structuredClone(state.draft),
      publishedBy: tenantId, // would use actual user ID
      publishedAt,
      changeNote: request.changeNote,
    };

    // 3. Store version
    await this.metadata.register('interface_version', `${request.interfaceName}__v${newVersion}`, versionEntry);

    // 4. Register published snapshot in metadata (this is what runtime serves)
    await this.metadata.register('interface', request.interfaceName, state.draft);

    // 5. Update draft state
    const updated: InterfaceDraftState = {
      ...state,
      status: 'published',
      publishedVersion: newVersion,
      publishedSnapshot: structuredClone(state.draft),
      lastPublishedAt: publishedAt,
      hasUnpublishedChanges: false,
    };
    await this.metadata.register('interface_draft', request.interfaceName, updated);

    return { success: true, version: newVersion, publishedAt };
  }

  // ... other methods follow same pattern ...
}
```

